import { base } from "$app/paths";
import type { CatalogEntry } from "$lib/catalog_data";
import type { PageLoad } from "./$types";

// The catalog is loaded as page data (catalog.json, generated by
// tools/build_catalog.ts) rather than imported: with the inline bundle
// strategy an import would put the whole catalog into every page.
export const load: PageLoad = async ({ fetch }) => {
    const response = await fetch(`${base}/catalog.json`);
    const catalog: CatalogEntry[] = await response.json();
    return { catalog };
};
